// Exercise gettime with both explicit and default-parameter forms while meeting API requirements.
// Assumptions/constraints enforced:
// - tp is non-null and points to writable memory (stack-allocated here).
// - We check the returned int; treat any nonzero as an error and bail.
// - On success, tv_nsec should be in [0, 1e9). We assert this property.
// Note: The build must include a visible definition of struct timespec (e.g., <time.h>).

struct timespec tp1 = {0};
struct timespec tp2 = {0};

// Randomly decide whether to request real-time or monotonic for the first call
bool needRealTime = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;

int rc1 = gettime(&tp1, needRealTime);
if (rc1 != 0) { FUZZ_BAIL(); }
// Property: tv_nsec must be within the valid nanosecond range
FUZZ_ASSERT(tp1.tv_nsec >= 0 && tp1.tv_nsec < 1000000000L, "tv_nsec out of range (explicit flag)");

// Second call uses the default parameter to exercise that path as well
int rc2 = gettime(&tp2);
if (rc2 != 0) { FUZZ_BAIL(); }
FUZZ_ASSERT(tp2.tv_nsec >= 0 && tp2.tv_nsec < 1000000000L, "tv_nsec out of range (default flag)");

// No persistent outputs to return; timespec values are ephemeral for this stub.
